// idl-conformance / cpp — DCPS roundtrip of a multi-feature IDL combo type.
//
// gen/combo.hpp is `zerodds-idlc generate --lang c++` output of combo.idl,
// generated by build.sh on every build. combo::Telemetry exercises, in one
// keyed topic type: enum (Mode), nested struct (Sample), sequence of struct
// (history), bounded string<32> (region, @key), union as a member (reading,
// switch(Mode)), map<string,long> (counters), @optional double
// (calibration), array long[4] (window), typedef (CurrentInAmpsType) and
// @key (unitId + region).
//
// Two samples go out through TypedWriter<Telemetry> over a ZeroDDS
// participant and come back through TypedReader<Telemetry>: the optional
// present with the union's MODE_ACTIVE case, then the optional absent with
// the union's default case. Every recovered field is compared with what was
// written.

#include "gen/combo.hpp"
#include "zerodds/dds.hpp"

#include <chrono>
#include <cstdio>
#include <optional>
#include <string>
#include <thread>

static int g_failures = 0;
#define CHECK(cond, what)                                                        \
    do {                                                                         \
        const bool ok_ = (cond);                                                 \
        std::printf("  [%s] %s\n", ok_ ? "PASS" : "FAIL", what);                 \
        if (!ok_) ++g_failures;                                                  \
    } while (0)

static combo::Telemetry sample(std::optional<double> calibration, combo::Reading reading) {
    combo::Telemetry t{};
    t.unitId = 42;
    t.region = "eu-central-mission-1";
    t.mode = combo::Mode::MODE_ACTIVE;
    t.batteryCurrent = 3.14159;
    t.history = {{1, 1.5}, {2, 2.5}, {3, -9.0}};
    t.reading = reading;
    t.counters = {{"drops", 0}, {"frames", 1000}, {"retries", 7}};
    t.calibration = calibration;
    t.window = {10, 20, 30, 40};
    return t;
}

static void compare(const combo::Telemetry& got, const combo::Telemetry& want) {
    CHECK(got.unitId == want.unitId && got.region == want.region, "keys unitId + region");
    CHECK(got.mode == want.mode, "enum member mode");
    CHECK(got.batteryCurrent == want.batteryCurrent, "typedef double batteryCurrent");
    bool history = got.history.size() == want.history.size();
    for (std::size_t i = 0; history && i < want.history.size(); ++i)
        history = got.history[i].seq == want.history[i].seq && got.history[i].value == want.history[i].value;
    CHECK(history, "sequence<Sample> history");
    CHECK(got.reading._d == want.reading._d, "union discriminator");
    if (want.reading._d == combo::Mode::MODE_ACTIVE)
        CHECK(got.reading.activeRate == want.reading.activeRate, "union case activeRate");
    else
        CHECK(got.reading.faultCode == want.reading.faultCode, "union default case faultCode");
    CHECK(got.counters == want.counters, "map<string,long> counters");
    CHECK(got.calibration == want.calibration, "@optional double calibration");
    CHECK(got.window == want.window, "long window[4]");
}

static bool take_within(zerodds::TypedReader<combo::Telemetry>& reader, combo::Telemetry& out,
                        std::chrono::milliseconds budget) {
    const auto deadline = std::chrono::steady_clock::now() + budget;
    while (std::chrono::steady_clock::now() < deadline) {
        if (reader.take(out)) return true;
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }
    return false;
}

int main(int argc, char** argv) {
    const uint32_t domain = argc > 1 ? static_cast<uint32_t>(std::stoul(argv[1])) : 177;
    zerodds::Runtime rt(domain);
    zerodds::TypedWriter<combo::Telemetry> writer(rt, "ComboTelemetry");
    zerodds::TypedReader<combo::Telemetry> reader(rt, "ComboTelemetry");
    if (!writer.wait_for_matched(1, 5000) || !reader.wait_for_matched(1, 5000)) {
        std::printf("ROUNDTRIP FAILED: writer and reader did not match\n");
        return 1;
    }

    combo::Reading active{};
    active._d = combo::Mode::MODE_ACTIVE;
    active.activeRate = 9.81;
    combo::Reading fault{};
    fault._d = combo::Mode::MODE_FAULT;
    fault.faultCode = "E_OVERHEAT";

    const combo::Telemetry sent[2] = {sample(0.999, active), sample(std::nullopt, fault)};
    for (const combo::Telemetry& want : sent) {
        std::printf("%s\n", want.calibration ? "optional present, union MODE_ACTIVE:"
                                             : "optional absent, union default:");
        writer.write(want);
        combo::Telemetry got{};
        if (!take_within(reader, got, std::chrono::milliseconds(3000))) {
            std::printf("  [FAIL] no sample arrived\n");
            ++g_failures;
            continue;
        }
        compare(got, want);
    }

    if (g_failures != 0) {
        std::printf("ROUNDTRIP FAILED: %d check(s)\n", g_failures);
        return 1;
    }
    std::printf("ROUNDTRIP OK: combo::Telemetry survived the DCPS wire, both samples\n");
    return 0;
}
